import {clamp,nearest} from './geometry.mjs';
const median=a=>a.sort((x,y)=>x-y)[Math.floor(a.length/2)]||0;
// Local geometric detector. No semantic/furniture recognition is claimed.
export function detectPlan(image,W,H,worldWidth,progress=()=>{}){
const gray=new Uint8Array(W*H),hist=new Uint32Array(256);for(let i=0;i<gray.length;i++){const k=i*4,alpha=image[k+3]/255,v=Math.round((image[k]*.299+image[k+1]*.587+image[k+2]*.114)*alpha+255*(1-alpha));gray[i]=v;hist[v]++}let total=0,sum=0;for(let i=0;i<256;i++)sum+=i*hist[i];let best=0,threshold=120,weight=0;for(let i=0;i<255;i++){weight+=hist[i];total+=i*hist[i];if(!weight||weight===gray.length)continue;const variance=weight*(gray.length-weight)*(total/weight-(sum-total)/(gray.length-weight))**2;if(variance>best){best=variance;threshold=i}}threshold=clamp(threshold+12,65,185);const mask=gray.map(v=>v<threshold?1:0),at=(x,y)=>x>=0&&y>=0&&x<W&&y<H?mask[Math.round(y)*W+Math.round(x)]||0:0;
const pts=[];for(let y=1;y<H-1;y++)for(let x=1;x<W-1;x++){const k=y*W+x;if(mask[k]&&(!mask[k-1]||!mask[k+1]||!mask[k-W]||!mask[k+W]))pts.push([x,y])}if(pts.length<30)return {walls:[],notes:['No se encontraron líneas suficientes. Usa una imagen nítida del plano.']};if(pts.length>W*H*.25)return {walls:[],notes:['La imagen contiene demasiado ruido. Recorta el plano y usa una foto frontal con fondo claro.']};
progress(20,'Buscando paredes y orientaciones…');const diag=Math.ceil(Math.hypot(W,H)),stride=diag*2+1,angles=90,acc=new Uint16Array(angles*stride),sample=Math.max(1,Math.ceil(pts.length/45000)),trig=[];for(let a=0;a<angles;a++){const th=a*Math.PI/angles,c=Math.cos(th),s=Math.sin(th);trig.push([c,s]);for(let i=0;i<pts.length;i+=sample){const [x,y]=pts[i],r=Math.round(x*c+y*s)+diag;acc[a*stride+r]++}}
const peaks=[],minLen=Math.max(22,Math.min(W,H)*.055);for(let a=0;a<angles;a++)for(let r=0;r<stride;r++)if(acc[a*stride+r]>minLen/sample*.65)peaks.push({a,r: r-diag,v:acc[a*stride+r]});peaks.sort((a,b)=>b.v-a.v);const chosen=[];for(const p of peaks){if(chosen.some(q=>Math.abs(q.a-p.a)<=1&&Math.abs(q.r-p.r)<5))continue;chosen.push(p);if(chosen.length>=150)break}
let lines=[];for(const peak of chosen){const [nx,ny]=trig[peak.a],tx=-ny,ty=nx;let begin=null,gap=0;const flush=end=>{if(begin===null||end-begin<minLen)return;const widths=[],offsets=[];for(let u=begin+5;u<end-4;u+=Math.max(4,(end-begin)/12)){const x=nx*peak.r+tx*u,y=ny*peak.r+ty*u;let center=null;for(let o=-3;o<=3;o++)if(at(x+nx*o,y+ny*o)){center=o;break}if(center===null)continue;let lo=center,hi=center;while(lo>-16&&at(x+nx*(lo-1),y+ny*(lo-1)))lo--;while(hi<16&&at(x+nx*(hi+1),y+ny*(hi+1)))hi++;widths.push(hi-lo+1);offsets.push((hi+lo)/2)}const r=peak.r+median(offsets),a={x:clamp((nx*r+tx*begin)/W,0,1),y:clamp((ny*r+ty*begin)/H,0,1)},b={x:clamp((nx*r+tx*end)/W,0,1),y:clamp((ny*r+ty*end)/H,0,1)};lines.push({a,b,type:'wall',pixels:median(widths),angle:peak.a,score:peak.v,inferred:true})};for(let t=-diag;t<=diag;t++){const x=nx*peak.r+tx*t,y=ny*peak.r+ty*t,hit=at(x,y)||at(x+nx,y+ny)||at(x-nx,y-ny);if(hit){if(begin===null)begin=t;gap=0}else if(begin!==null&&++gap>2){flush(t-gap);begin=null;gap=0}}if(begin!==null)flush(diag-gap)}
progress(55,'Uniendo trazos y limpiando duplicados…');lines.sort((a,b)=>Math.hypot((b.b.x-b.a.x)*W,(b.b.y-b.a.y)*H)*Math.sqrt(b.score)-Math.hypot((a.b.x-a.a.x)*W,(a.b.y-a.a.y)*H)*Math.sqrt(a.score));const merged=[];const ratio=H/W,tolerance=Math.max(8,Math.min(16,W*.022));for(const l of lines){const same=merged.find(q=>{const dot=((q.b.x-q.a.x)*(l.b.x-l.a.x)+(q.b.y-q.a.y)*(l.b.y-l.a.y)*ratio*ratio)/(Math.hypot(q.b.x-q.a.x,(q.b.y-q.a.y)*ratio)*Math.hypot(l.b.x-l.a.x,(l.b.y-l.a.y)*ratio));if(Math.abs(dot)<.94)return false;return nearest(l.a,q,W,H).d<tolerance&&nearest(l.b,q,W,H).d<tolerance});if(!same)merged.push(l);else same.pixels=Math.max(same.pixels,l.pixels)}
// Remove isolated thin lines (dimension strings, text and furniture strokes).
lines=merged.filter(l=>{if(l.pixels>=3)return true;let connections=0;for(const q of merged){if(q===l)continue;if(nearest(l.a,q,W,H).d<12||nearest(l.b,q,W,H).d<12)connections++}return connections>=2});if(!lines.length&&merged.length)lines=merged.filter(l=>Math.hypot((l.b.x-l.a.x)*W,(l.b.y-l.a.y)*H)>minLen*2.5);
lines=lines.slice(0,260);for(const l of lines){for(const key of ['a','b']){let best=8,target=null;for(const q of lines){if(q===l)continue;for(const p of [q.a,q.b]){const d=Math.hypot((l[key].x-p.x)*W,(l[key].y-p.y)*H);if(d>0&&d<best){best=d;target=p}}}if(target)l[key]={...target}}}
progress(75,'Buscando aberturas entre paredes…');const openings=[];for(let i=0;i<lines.length;i++)for(let j=i+1;j<lines.length;j++){const a=lines[i],b=lines[j],dx=(a.b.x-a.a.x)*W,dy=(a.b.y-a.a.y)*H,L=Math.hypot(dx,dy);if(!L)continue;const cross=p=>Math.abs((p.x-a.a.x)*W*dy-(p.y-a.a.y)*H*dx)/L;if(cross(b.a)>5||cross(b.b)>5)continue;let pair=null,gap=Infinity;for(const p of [a.a,a.b])for(const q of [b.a,b.b]){const d=Math.hypot((p.x-q.x)*W,(p.y-q.y)*H);if(d<gap){gap=d;pair=[p,q]}}const meters=gap/W*worldWidth;if(meters<.55||meters>1.6)continue;const [p,q]=pair,mid={x:(p.x+q.x)/2,y:(p.y+q.y)/2};if(lines.some(l=>l!==a&&l!==b&&nearest(mid,l,W,H).d<4)||openings.some(o=>nearest(mid,o,W,H).d<8))continue;let ink=0;for(let s=2;s<18;s++){const t=s/20;ink+=at((p.x+(q.x-p.x)*t)*W,(p.y+(q.y-p.y)*t)*H)}openings.push({a:{...p},b:{...q},type:ink>=10?'window':'door',inferred:true})}
const result=lines.map(({a,b,type,inferred})=>({a,b,type,inferred})).concat(openings);return {walls:result,notes:['Construcción geométrica aproximada: revisa paredes y aberturas resaltadas.','La escala y la altura usan tus ajustes; no se deducen de la foto.','Los muebles, textos, símbolos e instalaciones no se convierten en objetos 3D.'],stats:{segments:lines.length,openings:openings.length,threshold}};
}
